// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dep) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dep > 0);
        vm.assume(address(this).balance >= dep);
        uint256 beforeContractBal = address(c).balance;
        bool reverted;
        try c.deposit{value: dep}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterContractBal = address(c).balance;
        assertTrue(!reverted && afterContractBal == beforeContractBal + dep);
    }

    function testFuzz_run(uint256 dep) public {
        _run(dep);
    }

    receive() external payable {}
}
